  function boundedOutput(value){if(new TextEncoder().encode(JSON.stringify(value)).byteLength>3000000)throw new Error('Google output exceeds 3 MB transport budget; reduce page size/maxRows/maxPages or use one-page reads and narrower queries');return value;}
  function requireText(value,label,max=100000){if(typeof value!=='string'||!value.trim()||value.length>max)throw new Error(label+' must be nonempty text');return value;}
  function integer(value,label,min,max){const n=Number(value);if(!Number.isSafeInteger(n)||n<min||n>max)throw new Error(label+' is outside its integer bounds');return n;}
  function origin(provider){if(!config.mockOrigin)return provider;let u;try{u=new URL(config.mockOrigin);}catch{throw new Error('Invalid mockOrigin');}if(u.protocol!=='http:'||!['127.0.0.1','localhost','[::1]'].includes(u.hostname)||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw new Error('mockOrigin must be an explicit loopback HTTP origin');return u.origin;}
  function mockOAuthOrigin(){if(!config.oauthMockOrigin)return 'https://oauth2.googleapis.com';const old=config.mockOrigin;try{config.mockOrigin=config.oauthMockOrigin;return origin('https://oauth2.googleapis.com');}finally{config.mockOrigin=old;}}
  function secret(name,label){try{return requireText(context.secrets.get(requireText(name,label+' secret name',120)),label,100000);}catch{throw new Error('Missing or invalid '+label+' secret configuration');}}
  async function boundedJson(response,controller){const reader=response.body?.getReader();if(!reader)return {};const parts=[];let size=0;while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>integer(config.maxResponseBytes??8000000,'maxResponseBytes',1024,16000000)){controller.abort();throw new Error('Provider response exceeds configured byte bound');}parts.push(part.value);}const body=new Uint8Array(size);let offset=0;for(const part of parts){body.set(part,offset);offset+=part.length;}const text=new TextDecoder().decode(body);if(!text)return {};try{return JSON.parse(text);}catch{throw new Error('Provider returned invalid JSON');}}
  async function send(url,method,body,headers={},retry=true){const tries=retry?integer(config.readRetries??2,'readRetries',0,3)+1:1;for(let attempt=0;attempt<tries;attempt++){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),integer(config.requestTimeoutMs??15000,'requestTimeoutMs',100,120000));try{const response=await fetch(url,{method,headers,body:body===undefined?undefined:JSON.stringify(body),redirect:'error',signal:controller.signal});const data=await boundedJson(response,controller);if(response.ok)return {data,requestId:response.headers.get('request-id')||response.headers.get('x-request-id')||''};const code=typeof data?.error?.status==='string'&&/^[A-Z_]+$/.test(data.error.status)?data.error.status:'HTTP_ERROR';if([429,500,502,503,504].includes(response.status)&&attempt+1<tries){const raw=response.headers.get('retry-after');let delay=raw===null?Math.min(500*2**attempt,5000):/^\d+(\.\d+)?$/.test(raw)?Number(raw)*1000:Math.max(0,Date.parse(raw)-Date.now());if(!Number.isFinite(delay))delay=1000;if(delay>30000)throw new Error('Google '+response.status+' '+code+'; Retry-After exceeds bounded wait, retry later');clearTimeout(timer);await context.sleep(Math.max(0,Math.ceil(delay)));continue;}throw new Error('Google '+response.status+' '+code);}catch(error){if(error?.name==='AbortError'||controller.signal.aborted)throw new Error('Google request timed out or exceeded response bounds');if(error instanceof Error&&/^Google |^Provider /.test(error.message))throw error;throw new Error('Google transport failed; inspect endpoint/network configuration');}finally{clearTimeout(timer);}}throw new Error('Google request attempts exhausted');}
  async function accessToken(){if(config.authMode==='refreshToken'){const clientId=secret(config.clientIdSecret,'OAuth client ID'),clientSecret=secret(config.clientSecretSecret,'OAuth client secret'),refreshToken=secret(config.refreshTokenSecret,'OAuth refresh token');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),integer(config.requestTimeoutMs??15000,'requestTimeoutMs',100,120000));try{const response=await fetch(mockOAuthOrigin()+'/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'refresh_token',client_id:clientId,client_secret:clientSecret,refresh_token:refreshToken}).toString(),redirect:'error',signal:controller.signal});const data=await boundedJson(response,controller);if(!response.ok||typeof data.access_token!=='string'||!data.access_token)throw new Error('Google OAuth token refresh failed; renew consent/configuration');return data.access_token;}catch(error){if(error instanceof Error&&error.message.startsWith('Google OAuth'))throw error;throw new Error('Google OAuth token refresh failed; inspect network/configuration');}finally{clearTimeout(timer);}}return secret(config.accessTokenSecret,'OAuth access token');}
  function propertyId(){const id=String(config.propertyId??'').replace(/^properties\//,'');if(!/^\d+$/.test(id))throw new Error('propertyId must be a numeric GA4 property ID');return id;}
  function customerId(value,label='customerId'){const id=String(value??'').replace(/-/g,'');if(!/^\d{10}$/.test(id))throw new Error(label+' must contain exactly ten digits');return id;}
  function date(value,label){requireText(value,label,30);if(!/^(today|yesterday|\d+daysAgo|\d{4}-\d{2}-\d{2})$/.test(value))throw new Error(label+' must be YYYY-MM-DD, today, yesterday or NdaysAgo');if(/^\d{4}/.test(value)){const parsed=new Date(value+'T00:00:00Z');if(!Number.isFinite(parsed.valueOf())||parsed.toISOString().slice(0,10)!==value)throw new Error(label+' is not a calendar date');}return value;}
  function clone(value){return JSON.parse(JSON.stringify(value));}
  function filter(expression,depth=0){if(!expression||typeof expression!=='object'||Array.isArray(expression)||depth>20)throw new Error('Invalid or overly nested GA4 filter');const variants=['filter','andGroup','orGroup','notExpression'].filter(k=>expression[k]!==undefined);if(variants.length!==1||Object.keys(expression).some(k=>!variants.includes(k)))throw new Error('GA4 filter must specify exactly one expression variant');const k=variants[0];if(k==='notExpression')filter(expression[k],depth+1);else if(k==='andGroup'||k==='orGroup'){const es=expression[k]?.expressions;if(!Array.isArray(es)||!es.length||es.length>100)throw new Error('GA4 filter group requires 1–100 expressions');for(const e of es)filter(e,depth+1);}else{const f=expression.filter;requireText(f?.fieldName,'Filter fieldName',200);const ks=['stringFilter','inListFilter','numericFilter','emptyFilter'].filter(x=>f[x]!==undefined);if(ks.length!==1)throw new Error('GA4 leaf filter requires one supported filter');if(ks[0]==='numericFilter'){const v=f.numericFilter.value||{};if((v.int64Value===undefined)===(v.doubleValue===undefined))throw new Error('Numeric filter requires one numeric value variant');}}return expression;}
  function reportRequest(request){if(!request||typeof request!=='object'||!Array.isArray(request.metrics)||!request.metrics.length||request.metrics.length>10||!Array.isArray(request.dateRanges)||!request.dateRanges.length||request.dateRanges.length>4)throw new Error('GA4 report requires 1–10 metrics and 1–4 date ranges');if((request.dimensions||[]).length>9)throw new Error('GA4 supports at most nine dimensions');for(const d of request.dimensions||[])requireText(d.name,'Dimension name',200);for(const m of request.metrics)requireText(m.name,'Metric name',200);for(const range of request.dateRanges){date(range.startDate,'startDate');date(range.endDate,'endDate');if(/^\d{4}/.test(range.startDate)&&/^\d{4}/.test(range.endDate)&&range.startDate>range.endDate)throw new Error('startDate must not follow endDate');}if(request.dimensionFilter)filter(request.dimensionFilter);if(request.metricFilter)filter(request.metricFilter);return clone(request);}
  function namedRows(report){const dimensions=report.dimensionHeaders||[],metrics=report.metricHeaders||[];const names=[...dimensions,...metrics].map(h=>h.name);if(new Set(names).size!==names.length||names.some(n=>typeof n!=='string'||['__proto__','prototype','constructor'].includes(n)))throw new Error('GA4 report has duplicate or unsafe column names');return(report.rows||[]).map(row=>{const d=row.dimensionValues||[],m=row.metricValues||[];if(d.length!==dimensions.length||m.length!==metrics.length)throw new Error('GA4 row/header width mismatch');const out={dimensions:{},metrics:{}};for(let i=0;i<d.length;i++){if(typeof d[i].value!=='string')throw new Error('GA4 dimension value must be text');out.dimensions[dimensions[i].name]=d[i].value;}for(let i=0;i<m.length;i++){if(typeof m[i].value!=='string')throw new Error('GA4 metric value must be text');out.metrics[metrics[i].name]=m[i].value;}return out;});}
  function gaql(query){requireText(query,'GAQL query');if(!/^\s*SELECT\b/i.test(query)||!/\bFROM\s+[a-z][a-z_]*\b/i.test(query)||/;|--|\/\*/.test(query))throw new Error('Only one SELECT GAQL statement without comments is allowed');return query;}
  async function adsHeaders(){const h={Authorization:'Bearer '+await accessToken(),'developer-token':secret(config.developerTokenSecret,'Ads developer token'),'Content-Type':'application/json'};if(config.loginCustomerId)h['login-customer-id']=customerId(config.loginCustomerId,'loginCustomerId');return h;}
  function adsVersion(){const version=config.apiVersion??'v26';if(!/^v\d+$/.test(version))throw new Error('apiVersion must be a Google Ads major version such as v26');return version;}
  function micros(value){const text=String(value??'0');if(!/^-?\d+$/.test(text))throw new Error('costMicros must be an integer string');const n=BigInt(text);const abs=n<0n?-n:n;return(n<0n?'-':'')+(abs/1000000n).toString()+'.'+(abs%1000000n).toString().padStart(6,'0');}
return boundedOutput(await (async()=>{const query=gaql(inputs.query??config.query);return {request:{query,returnTotalResultsCount:config.returnTotalResultsCount??false,...(config.pageToken?{pageToken:config.pageToken}:{})}};})());

